func pageRect(_ page: Int) -> NSRect {
    let x = page == 0 ? m : gutter + m
    return NSRect(x: x, y: m, width: gutter - m * 2, height: SH - m * 2)
}

func twoPortraitSlots(page: Int, names: [String]) -> [Slot] {
    let r = pageRect(page)
    let gap: CGFloat = 22
    let w = (r.width - gap) / 2
    return [
        Slot(name: names[0], rect: NSRect(x: r.minX, y: r.minY, width: w, height: r.height), fill: false),
        Slot(name: names[1], rect: NSRect(x: r.minX + w + gap, y: r.minY, width: w, height: r.height), fill: false)
    ]
}

func landscapeSlot(page: Int, name: String) -> Slot {
    Slot(name: name, rect: pageRect(page), fill: true)
}

func singlePortrait(page: Int, name: String) -> Slot {
    let r = pageRect(page)
    let h = r.height
    let w = h * (2.0 / 3.0)
    let x = r.midX - w / 2
    return Slot(name: name, rect: NSRect(x: x, y: r.minY, width: w, height: h), fill: true)
}

