func drawImage(_ name: String, in rect: NSRect, fill: Bool) {
    let path = src + "/" + name + ".jpg"
    guard let img = NSImage(contentsOfFile: path) else { return }
    let pw = img.size.width
    let ph = img.size.height
    if fill {
        let scale = max(rect.width / pw, rect.height / ph)
        let dw = pw * scale
        let dh = ph * scale
        let dx = rect.midX - dw / 2
        let dy = rect.midY - dh / 2
        NSGraphicsContext.current?.cgContext.saveGState()
        NSBezierPath(rect: rect).addClip()
        img.draw(in: NSRect(x: dx, y: dy, width: dw, height: dh))
        NSGraphicsContext.current?.cgContext.restoreGState()
    } else {
        let scale = min(rect.width / pw, rect.height / ph)
